export function validateRESPIRATORYSeed(): void {
  const slugs = new Set(
    RESPIRATORY_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== RESPIRATORY_STRUCTURES.length) {
    throw new Error(
      'Respiratory system seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    RESPIRATORY_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== RESPIRATORY_STRUCTURES.length) {
    throw new Error('Respiratory system seed contains duplicate mesh names.');
  }
  if (RESPIRATORY_STRUCTURES.length !== 26) {
    throw new Error(
      'Respiratory system seed must contain exactly 26 structures.',
    );
  }
  for (const structure of RESPIRATORY_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
    if (
      [
        structure.summary,
        structure.location,
        structure.function,
        structure.bloodSupply,
        structure.clinicalNotes,
      ].some((value) => value.trim().length > 0)
    ) {
      throw new Error(
        `Structure "${structure.slug}" must not contain teaching text until faculty review.`,
      );
    }
  }
}
